import ast
from pathlib import Path

def pub(module):
    tree = ast.parse(module.read_text(encoding='utf-8'))
    rows = []
    for node in tree.body:
        if isinstance(node, ast.FunctionDef) and not node.name.startswith('_'):
            doc = (ast.get_docstring(node) or '').splitlines()
            rows.append((node.name, 'def ' + node.name + '(' + ast.unparse(node.args) + ')', doc[0].strip() if doc else ''))
    return sorted(rows)

def tag(module):
    for node in ast.parse(module.read_text(encoding='utf-8')).body:
        if isinstance(node, ast.Assign) and getattr(node.targets[0], 'id', '') == 'AUDIT_TAG':
            return node.value.value
    raise AssertionError('源模块没有 AUDIT_TAG')

sources = sorted(Path('ledger').glob('part_*.py'))
assert len(sources) == 8, [str(s) for s in sources]
imported = 0
for source in sources:
    summary = Path('reports') / (source.stem + '_summary.py')
    assert summary.is_file(), f'缺 {summary}'
    ns = {}
    exec(compile(ast.parse(summary.read_text(encoding='utf-8')), str(summary), 'exec'), ns)
    assert sorted(tuple(r) for r in ns['API']) == pub(source), f'{summary.name} 的 API 与源文件不一致'
    assert ns['SOURCE'] == source.as_posix(), ns['SOURCE']
    assert ns['AUDIT_TAG'] == tag(source), f'{summary.name} 的 AUDIT_TAG 抄错了'
    imported += len(ns['API'])
assert imported >= 750, f'汇总了 {imported} 个函数，八个模块应有 800 个'
assert Path('tests/test_rollups.py').is_file(), '没写汇总层的契约测试'
